using System;
using System.IO;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Volo.Abp.Cli.Commands;

namespace Volo.Abp.Cli.Tests
{
    public class SuiteCommandTests
    {
        [Fact]
        public async Task GenerateCrudPageAsync_Should_LogError_When_ResponseContainsError()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<SuiteCommand>>();
            var httpClientMock = new Mock<HttpClient>();
            var cliHttpClientFactoryMock = new Mock<IVirtualHttpClientFactory>();
            var cmdHelperMock = new Mock<ICmdHelper>();

            // Setup the factory to return a HttpClient that returns a response with error message
            var responseContent = new StringContent("Error: Something went wrong");
            var responseMessage = new HttpResponseMessage
            {
                Content = responseContent
            };

            var httpClientHandlerMock = new Mock<HttpMessageHandler>();
            httpClientHandlerMock
                .Setup(m => m.Send(It.IsAny<HttpRequestMessage>()))
                .ReturnsAsync(responseMessage);

            var client = new HttpClient(httpClientHandlerMock.Object);

            // Setup the factory to return our HttpClient
            cliHttpClientFactoryMock
                .Setup(f => f.CreateClient(It.IsAny<bool>()))
                .Returns(client);

            var suiteCommand = new SuiteCommand(
                new Mock<AbpNuGetIndexUrlService>().Object,
                new Mock<PackageVersionCheckerService>().Object,
                cmdHelperMock.Object,
                new Mock<AuthService>().Object,
                cliHttpClientFactoryMock.Object,
                new Mock<SuiteAppSettingsService>().Object
            )
            {
                Logger = loggerMock.Object
            };

            // Create dummy file
            var tempEntityFile = Path.GetTempFileName();
            File.WriteAllText(tempEntityFile, "{}");
            var args = new CommandLineArgs
            {
                Options = new System.Collections.Generic.Dictionary<string, string>
                {
                    {Options.Crud.Entity.Short, tempEntityFile},
                    {Options.Crud.Solution.Short, "dummy.sln"}
                }
            };

            // Mock GetSolutionIdAsync to return a dummy Guid
            var suiteCommandPrivate = new PrivateObject(suiteCommand);
            suiteCommandPrivate.SetFieldOrProperty("_abpSuitePort", 3000);
            suiteCommandPrivate.SetFieldOrProperty("Logger", loggerMock.Object);

            // Act
            await suiteCommand.GenerateCrudPageAsync(args);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error: Something went wrong")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
